</head>
<body>
    <canvas id="gameCanvas"></canvas>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        let player = {
            x: 50,
            y: canvas.height - 70,
            width: 50,
            height: 50,
            color: 'red',
            velocityY: 0,
            isJumping: false,
            velocityX: 0,
            playerSpeed: 5,
            isAlive: true,
            score: 0,
            hasDoubleJump: false
        };

        let gravity = 0.5;
        let jumpStrength = -10;
        let cameraX = 0;

        let platforms = [
            { x: 0, y: canvas.height - 20, width: canvas.width * 2, height: 20, color: 'green', type: 'static' }, // Ground expanded
            { x: 200, y: canvas.height - 100, width: 150, height: 20, color: 'brown', type: 'static' },
            { x: 400, y: canvas.height - 200, width: 150, height: 20, color: 'brown', type: 'crumbling', crumbleTimer: 0 },
            { x: 600, y: canvas.height - 150, width: 150, height: 20, color: 'brown', type: 'moving', originalX: 600, speed: 1, direction: 1, moveRange: 100 },
            { x: 800, y: canvas.height - 100, width: 150, height: 20, color: 'brown', type: 'static' },
            { x: 1000, y: canvas.height - 250, width: 200, height: 20, color: 'brown', type: 'moving', originalX: 1000, speed: 1.5, direction: -1, moveRange: 150 },
            { x: 1300, y: canvas.height - 180, width: 100, height: 20, color: 'brown', type: 'crumbling', crumbleTimer: 0 },
            { x: 1600, y: canvas.height - 70, width: 50, height: 50, color: 'gold', type: 'static' } // Win platform
        ];

        let collectibles = [
            { x: 250, y: canvas.height - 130, width: 20, height: 20, color: 'yellow', value: 5 },
            { x: 700, y: canvas.height - 180, width: 20, height: 20, color: 'yellow', value: 5 },
            { x: 1100, y: canvas.height - 280, width: 20, height: 20, color: 'yellow', value: 5 }
        ];

        let enemies = [
            { x: 300, y: canvas.height - 40, width: 30, height: 30, color: 'purple', speed: 2, direction: 1, type: 'ground' },
            { x: 700, y: canvas.height - 40, width: 30, height: 30, color: 'purple', speed: 2, direction: -1, type: 'ground' },
            { x: 1200, y: 150, width: 40, height: 40, color: 'darkred', speed: 1.5, direction: 1, type: 'flying', shootInterval: 120, lastShotTime: 0 }
        ];

        let projectiles = [];

        let powerUps = [
            { x: 500, y: canvas.height - 150, width: 20, height: 20, color: 'blue', type: 'doubleJump' }
        ];

        function checkCollision(obj1, obj2) {
            return obj1.x < obj2.x + obj2.width &&
                   obj1.x + obj1.width > obj2.x &&
                   obj1.y < obj2.y + obj2.height &&
                   obj1.y + obj1.height > obj2.y;
        }

        function update() {
            if (!player.isAlive) {
                return; // Stop updating if player is dead
            }

            // Apply gravity
            player.velocityY += gravity;
            player.y += player.velocityY;

            // Apply horizontal movement
            player.x += player.velocityX;

            // Camera scrolling
            if (player.x < cameraX + canvas.width * 0.3) {
                cameraX = player.x - canvas.width * 0.3;
            }
            if (player.x > cameraX + canvas.width * 0.7) {
                cameraX = player.x - canvas.width * 0.7;
            }

            cameraX = Math.max(0, cameraX); // Keep camera from going too far left

            // Check for collisions with platforms
            for (let i = 0; i < platforms.length; i++) {
                let platform = platforms[i];

                // Update moving platforms
                if (platform.type === 'moving') {
                    platform.x += platform.speed * platform.direction;
                    if (platform.x > platform.originalX + platform.moveRange || platform.x < platform.originalX - platform.moveRange) {
                        platform.direction *= -1; // Reverse direction
                    }
                }

                if (checkCollision(player, { ...platform, x: platform.x - cameraX })) {
                    if (player.velocityY > 0) {
                        player.y = platform.y - player.height; // Snap to top of platform
                        player.velocityY = 0;
                        player.isJumping = false;

                        // Crumbling platform logic
                        if (platform.type === 'crumbling') {
                            platform.crumbleTimer = 1; // Start crumbling
                        }
                    }
                }

                // Crumbling platform mechanics
                if (platform.type === 'crumbling' && platform.crumbleTimer > 0) {
                    platform.crumbleTimer++;
                    if (platform.crumbleTimer > 30) { // Crumble after 30 frames
                        // For now, let's just make it non-collidable and eventually disappear
                        // A more advanced approach would involve removing it from the array or changing its state
                        platform.color = 'transparent'; // Visually disappear
                        // To make it actually disappear, you would need to remove it from the platforms array
                        // For this example, making it transparent and non-collidable is sufficient to simulate crumbling
                    }
                }
            }

            // Power-up collision
            for (let i = 0; i < powerUps.length; i++) {
                let powerUp = powerUps[i];
                if (checkCollision(player, { ...powerUp, x: powerUp.x - cameraX })) {
                    if (powerUp.type === 'doubleJump') {
                        player.hasDoubleJump = true;
                        console.log("Double Jump acquired!");
                    }
                    powerUps.splice(i, 1);
                    i--;
                }
            }

            // Update and draw projectiles
            for (let i = 0; i < projectiles.length; i++) {
                let projectile = projectiles[i];
                projectile.x += projectile.velocityX;
                projectile.y += projectile.velocityY;

                // Check projectile-player collision
                if (checkCollision(player, { ...projectile, x: projectile.x - cameraX })) {
                    alert('Game Over! You were hit by a projectile.');
                    player.isAlive = false;
                    projectiles.splice(i, 1);
                    i--;
                    continue;
                }

                // Remove projectiles that go off-screen
                if (projectile.x - cameraX < -projectile.width || projectile.x - cameraX > canvas.width ||
                    projectile.y < -projectile.height || projectile.y > canvas.height) {
                    projectiles.splice(i, 1);
                    i--;
                }
            }

            // Prevent player from falling through the ground (the first platform is the ground)
            if (player.y + player.height > platforms[0].y) {
                player.y = platforms[0].y - player.height;
                player.velocityY = 0;
                player.isJumping = false;
            }

            // Enemy AI and collision
            for (let i = 0; i < enemies.length; i++) {
                let enemy = enemies[i];

                if (enemy.type === 'ground') {
                    enemy.x += enemy.speed * enemy.direction;

                    // Simple enemy patrol within a range (adjust as needed)
                    if (enemy.direction === 1 && enemy.x > platforms[0].x + 400 + (i * 200)) { // Patrol limit example
                        enemy.direction = -1;
                    } else if (enemy.direction === -1 && enemy.x < platforms[0].x + 200 + (i * 200)) {
                        enemy.direction = 1;
                    }
                } else if (enemy.type === 'flying') {
                    // Simple flying enemy movement (e.g., patrol horizontally)
                    enemy.x += enemy.speed * enemy.direction;
                    if (enemy.x > 1500 || enemy.x < 1000) { // Patrol between X=1000 and X=1500
                        enemy.direction *= -1;
                    }

                    // Flying enemy shoots projectiles
                    if (player.isAlive && Date.now() - enemy.lastShotTime > enemy.shootInterval * 10) { // Using Date.now for time
                        let projectile = {
                            x: enemy.x + enemy.width / 2,
                            y: enemy.y + enemy.height,
                            width: 10,
                            height: 10,
                            color: 'orange',
                            speed: 8,
                            velocityY: 0,
                        };
                        // Calculate direction towards player
                        let angle = Math.atan2(player.y - projectile.y, (player.x - cameraX) - projectile.x);
                        projectile.velocityX = Math.cos(angle) * projectile.speed;
                        projectile.velocityY = Math.sin(angle) * projectile.speed;
                        projectiles.push(projectile);
                        enemy.lastShotTime = Date.now();
                    }
                }

                // Check player-enemy collision
                if (checkCollision(player, { ...enemy, x: enemy.x - cameraX })) {
                    // Player stomps on enemy (simple example: if player is falling)
                    if (player.velocityY > 0) {
                        enemies.splice(i, 1); // Remove enemy
                        player.velocityY = jumpStrength / 2; // Small bounce
                        player.score += 10; // Increase score
                        i--; // Adjust index due to removal
                    } else {
                        // Player hit by enemy from side or bottom
                        alert('Game Over! You were defeated.');
                        player.isAlive = false;
                    }
                }
            }

            // Collectible item collision
            for (let i = 0; i < collectibles.length; i++) {
                let collectible = collectibles[i];
                if (checkCollision(player, { ...collectible, x: collectible.x - cameraX })) {
                    player.score += collectible.value; // Add collectible value to score
                    collectibles.splice(i, 1); // Remove collected item
                    i--; // Adjust index due to removal
                }
            }
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw player
            ctx.fillStyle = player.color;
            ctx.fillRect(player.x - cameraX, player.y, player.width, player.height);

            // Draw platforms
            for (let i = 0; i < platforms.length; i++) {
                let platform = platforms[i];
                ctx.fillStyle = platform.color;
                ctx.fillRect(platform.x - cameraX, platform.y, platform.width, platform.height);
            }

            // Draw enemies
            for (let i = 0; i < enemies.length; i++) {
                let enemy = enemies[i];
                ctx.fillStyle = enemy.color;
                ctx.fillRect(enemy.x - cameraX, enemy.y, enemy.width, enemy.height);
            }

            // Draw projectiles
            for (let i = 0; i < projectiles.length; i++) {
                let projectile = projectiles[i];
                ctx.fillStyle = projectile.color;
                ctx.fillRect(projectile.x - cameraX, projectile.y, projectile.width, projectile.height);
            }

            // Draw collectibles
            for (let i = 0; i < collectibles.length; i++) {
                let collectible = collectibles[i];
                ctx.fillStyle = collectible.color;
                ctx.fillRect(collectible.x - cameraX, collectible.y, collectible.width, collectible.height);
            }

            // Draw power-ups
            for (let i = 0; i < powerUps.length; i++) {
                let powerUp = powerUps[i];
                ctx.fillStyle = powerUp.color;
                ctx.fillRect(powerUp.x - cameraX, powerUp.y, powerUp.width, powerUp.height);
            }

            // Draw score
            ctx.fillStyle = 'black';
            ctx.font = '20px Arial';
            ctx.fillText(`Score: ${player.score}`, 20, 30);
        }

        function drawGameOverScreen() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'black';
            ctx.font = '50px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 40);
            ctx.font = '30px Arial';
            ctx.fillText(`Final Score: ${player.score}`, canvas.width / 2, canvas.height / 2 + 10);
            ctx.font = '20px Arial';
            ctx.fillText('Press R to Restart', canvas.width / 2, canvas.height / 2 + 60);
        }

        function gameLoop() {
            if (player.isAlive) {
                update();
                draw();
            } else {
                drawGameOverScreen();
            }
            requestAnimationFrame(gameLoop);
        }

        document.addEventListener('keydown', (e) => {
            if (e.code === 'Space' && player.isAlive) {
                if (!player.isJumping) {
                    player.velocityY = jumpStrength;
                    player.isJumping = true;
                } else if (player.hasDoubleJump) {
                    player.velocityY = jumpStrength; // Apply jump strength for double jump
                    player.hasDoubleJump = false; // Consume double jump
                }
            } else if (e.code === 'ArrowLeft' && player.isAlive) {
                player.velocityX = -player.playerSpeed;
            } else if (e.code === 'ArrowRight' && player.isAlive) {
                player.velocityX = player.playerSpeed;
            }
        });

        document.addEventListener('keyup', (e) => {
            if ((e.code === 'ArrowLeft' || e.code === 'ArrowRight') && player.isAlive) {
                player.velocityX = 0;
            }
        });

        gameLoop();
    </script>
</body>
</html>",
