        "+<!DOCTYPE html>",
        "+<html>",
        "+<head>",
        "+    <title>Albert's Stress Test</title>",
        "+</head>",
        "+<style>",
        "+        body { margin: 0; overflow: hidden; background: #87CEEB; }",
