        "+</head>",
        "+<body>",
        "+    <canvas id="gameCanvas"></canvas>",
        "+",
        "+    <script>",
        "+        const canvas = document.getElementById('gameCanvas');",
        "+        const ctx = canvas.getContext('2d');",
        "+",
        "+        canvas.width = window.innerWidth;",
        "+        canvas.height = window.innerHeight;",
        "+",
        "+        let player = {",
        "+            x: 50,",
        "+            y: canvas.height - 70,",
        "+            width: 50,",
        "+            height: 50,",
        "+            color: 'red',",
        "+            velocityY: 0,",
        "+            isJumping: false,",
        "+            velocityX: 0,",
        "+            playerSpeed: 5,",
        "+            isAlive: true,",
        "+            score: 0,",
        "+            hasDoubleJump: false",
        "+        };",
        "+",
        "+        let gravity = 0.5;",
        "+        let jumpStrength = -10;",
        "+        let cameraX = 0;",
        "+",
        "+        let platforms = [",
        "+            { x: 0, y: canvas.height - 20, width: canvas.width * 2, height: 20, color: 'green', type: 'static' }, // Ground expanded",
        "+            { x: 200, y: canvas.height - 100, width: 150, height: 20, color: 'brown', type: 'static' },",
        "+            { x: 400, y: canvas.height - 200, width: 150, height: 20, color: 'brown', type: 'crumbling', crumbleTimer: 0 },",
        "+            { x: 600, y: canvas.height - 150, width: 150, height: 20, color: 'brown', type: 'moving', originalX: 600, speed: 1, direction: 1, moveRange: 100 },",
        "+            { x: 800, y: canvas.height - 100, width: 150, height: 20, color: 'brown', type: 'static' },",
        "+            { x: 1000, y: canvas.height - 250, width: 200, height: 20, color: 'brown', type: 'moving', originalX: 1000, speed: 1.5, direction: -1, moveRange: 150 },",
        "+            { x: 1300, y: canvas.height - 180, width: 100, height: 20, color: 'brown', type: 'crumbling', crumbleTimer: 0 },",
        "+            { x: 1600, y: canvas.height - 70, width: 50, height: 50, color: 'gold', type: 'static' } // Win platform",
        "+        ];",
