        "+                    i--;",
        "+                    continue;",
        "+                }",
        "+",
        "+                // Remove projectiles that go off-screen",
        "+                if (projectile.x - cameraX < -projectile.width || projectile.x - cameraX > canvas.width ||",
        "+                    projectile.y < -projectile.height || projectile.y > canvas.height) {",
